const STORE='kin.family.v1:'+location.pathname;
const familyStore=createFamilyStore(STORE,()=>localStorage);
let installPrompt=null,toastTimer,offlineState='preparing',noticeState=null;
const initials=name=>name.trim().split(/\s+/).map(x=>Array.from(x)[0]).slice(0,2).join('').toLocaleUpperCase();
const familyURL=rows=>location.origin+location.pathname+encode(rows);
const {modal,close,confirmLeave}=createDialogs(state);
const workbench=createWorkbench(state,{modal,close,render,toast,ics:openCalendarExport});
const comfort=createComfort(state,{device:workbench.device,render});
workbench.setDocuments(async event=>{if(state.demo)return toast('Example data is not saved. Start your own family first.');try{const {openDocumentDialog}=await import('./document-ui.js');openDocumentDialog(state,{modal,close,toast,visible:workbench.visible,device:workbench.device},event)}catch{toast('Export could not be created. Try again.')}});
function drawNotice(){const n=$('#notice');n.hidden=!noticeState;if(!noticeState)return;n.textContent=typeof noticeState.message==='function'?noticeState.message():t(noticeState.message);if(noticeState.action){const b=document.createElement('button');b.textContent=t(noticeState.label);b.onclick=noticeState.action;n.append(b)}}
function notice(message,action,label){noticeState={message,action,label};drawNotice()}
function clearNotice(){noticeState=null;drawNotice()}
function damagedLink(error){notice(()=>errorText(error)+' '+t('Your local family has not been replaced.'),()=>{history.replaceState(null,'',location.pathname+(state.people.length?encode(state.people):''));clearNotice()},'Use local family')}
function toast(key,action=null,label='Undo'){const el=$('#toast');$('#toast-text').textContent=t(key);el.hidden=false;$('#toast-action').hidden=!action;$('#toast-action').textContent=t(label);$('#toast-action').onclick=()=>{el.hidden=true;action?.()};clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,action?12000:4500)}
function localFamily(){try{return familyStore.load()}catch{notice('The local copy could not be read. Open your saved family link to recover it.');return []}}
async function commit(rows,options){
 if(state.saving)return false;state.saving=true;$('#modal').setAttribute('aria-busy','true');$('#close-modal').disabled=true;
 try{return await familyStore.serialize(()=>commitNow(rows,options))}
 catch{toast('Could not save right now. Try again or copy your current family link.');return false}
 finally{state.saving=false;$('#modal').removeAttribute('aria-busy');$('#close-modal').disabled=false}
}
function commitNow(rows,{message='Family link updated. Save a fresh bookmark.'}={}){
 try{
  const result=familyStore.write(rows);
  if(result.conflict){notice('Your family changed in another tab. Review it before continuing.',reviewLatest,'Review changes');toast('Your family changed in another tab. Close this form and review the changes first.');return false}
  history.replaceState(null,'',location.pathname+result.hash);state.people=rows;state.demo=false;state.viewOnly=false;state.undoState=null;clearNotice();
  if(!result.persisted)notice('Browser storage is unavailable. Your family is still in this URL—copy or bookmark it before closing.');
  render();if(message)toast(message);return true;
 }catch(e){toast(errorText(e));return false}
}
function reviewLatest(){if(!close())return;const current=[...state.people];state.people=localFamily();state.viewOnly=false;render();review(current,false)}
function localizedShell(){document.documentElement.lang=language();document.documentElement.dir=language()==='ar'?'rtl':'ltr';document.title=language()==='ar'?'كِن — عائلتك مع مرور الأيام':'Kin — Family, through time';$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$('#language-button').textContent=language()==='ar'?'English':'العربية';$('#language-button').lang=language()==='ar'?'en':'ar';$('#language-button').setAttribute('aria-label',language()==='ar'?'Switch to English':'التبديل إلى العربية');$('#family-search').placeholder=t('Search your family…');$('.brand').setAttribute('aria-label',t('Kin home'));$('.overview').setAttribute('aria-label',t('Family overview'));$('#close-modal').setAttribute('aria-label',t('Close dialog'));$('.view-tabs').setAttribute('aria-label',t('Family views'));drawNotice();offlineUI()}
function offlineUI(){const states={preparing:['Preparing offline mode','One online visit, then take it with you.'],ready:['Ready for offline',navigator.onLine?'Your circle goes wherever you go.':'You’re offline. Your family still works here.'],failed:['Offline setup unavailable','Stay online for now. Your saved link still works.'],unsupported:['Online mode','This browser does not support offline setup.']};const [a,b]=states[offlineState];$('#offline-label').textContent=t(a);$('#offline-detail').textContent=t(b);$('#offline-symbol').innerHTML=icon({preparing:'clock',ready:'offline',failed:'warning',unsupported:'globe'}[offlineState])}
function sorted(){return workbench.visible().sort((a,b)=>state.sort==='name'?a.name.localeCompare(b.name,language()):state.sort==='oldest'?a.day-b.day:state.sort==='birthday'?(nextEvent(a,Math.max(a.day,state.now),state.primaryCalendar)?.day??Infinity)-(nextEvent(b,Math.max(b.day,state.now),state.primaryCalendar)?.day??Infinity):state.people.indexOf(b)-state.people.indexOf(a))}
function render(){state.now=state.reference??today();$('#member-count').textContent=number(state.people.length);$('#list-count').textContent=number(state.people.length);$('#today-g').textContent=date(state.now);$('#today-h').textContent=date(state.now,'h');$('#mini-avatars').innerHTML=state.people.slice(0,3).map(p=>`<span>${esc(initials(p.name))}</span>`).join('');
const events=workbench.visible().flatMap(p=>['g','h'].map(c=>{const e=nextEvent(p,Math.max(state.now,p.day),c);return e?{p,c,...e,inDays:e.day-state.now}:null}).filter(Boolean)).sort((a,b)=>a.inDays-b.inDays);
if(events.length){const e=events[0];$('#next-event').innerHTML=`<bdi>${esc(e.p.name)}</bdi><span aria-hidden="true"> · </span><bdi>${esc(e.inDays===0?t('Today!'):t('{days} away',{days:quantity(e.inDays,'day')}))}</bdi>`;$('#next-detail').textContent=t('{calendar} birthday · {date}',{calendar:calendarName(e.c),date:date(e.day,e.c)})}else{$('#next-event').textContent=t(state.people.length?'No birthdays in this view':'A birthday to look forward to');$('#next-detail').textContent=t(state.people.length?'Try clearing the family filters.':'Add your first person below')}$('#see-birthdays').hidden=!events.length;
$('#share-button').disabled=!state.people.length;const visible=sorted();$('#list-count').textContent=number(visible.length);
$('#people').innerHTML=state.people.length?(visible.length?(state.layout==='table'?peopleTable(visible,state):visible.map(card).join('')):`<div class="empty search-empty"><h3>${t('No matching names')}</h3><p>${t('Try another name or clear your search.')}</p>${button('clear-search','Clear search')}</div>`):`<div class="empty"><div class="empty-symbol" aria-hidden="true">k.</div><h3>${t('Your story starts with a name.')}</h3><p>${t('Add someone you love. We’ll keep track of the years, the days, and the next reason to celebrate.')}</p><button class="quiet" id="demo-button">${t('Take a look with an example family')}</button></div>`;
renderAgenda();workbench.refresh();comfort.refresh();
$('#demo-button')?.addEventListener('click',showDemo);$('#clear-search')?.addEventListener('click',()=>{state.search='';$('#family-search').value='';render();$('#family-search').focus()});$$('[data-edit]').forEach(b=>b.onclick=()=>editPerson(state.people.find(p=>p.id===b.dataset.edit)));
}

function renderAgenda(){
 $('#people').hidden=state.view!=='people';$('#birthday-panel').hidden=state.view!=='birthdays';$('.sort-label').hidden=state.view!=='people';
 $$('[data-view]').forEach(b=>{const active=b.dataset.view===state.view;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});
 if(state.view!=='birthdays')return;
 state.agendaEvents=listBirthdays(workbench.visible(),{from:state.now,days:state.birthdayRange,calendar:state.birthdayCalendar}).filter(e=>!state.milestones.length||state.milestones.includes(e.turns));

 $('#agenda-summary').textContent=t('{count} birthdays · {from} — {to}',{count:number(state.agendaEvents.length),from:date(state.now),to:date(Math.min(MAX,state.now+state.birthdayRange-1))});
 let month='';$('#birthday-list').innerHTML=state.agendaEvents.length?state.agendaEvents.map(e=>{const [year,m,day]=calendars.g.parts(e.day),key=year+'-'+m;let heading='';if(month!==key){month=key;heading=`<h3 class="agenda-month">${months('g')[m-1]} ${number(year).replace(/[٬,]/g,'')}</h3>`}return heading+`<article class="agenda-event"><div class="agenda-day" aria-hidden="true"><strong>${number(day)}</strong><span>${weekday(e.day)}</span></div><div class="agenda-person"><span class="sr-only">${date(e.day)} · ${weekday(e.day)}</span><h4 dir="auto">${esc(e.person.name)}</h4><p>${icon(e.calendar==='g'?'sun':'moon')}${calendarName(e.calendar)} · ${t('Turning {age}',{age:quantity(e.turns,'year')})}</p>${e.calendar==='h'?`<p class="agenda-hijri">${date(e.day,'h')}</p>`:''}<button class="quiet" data-agenda-card="${state.agendaEvents.indexOf(e)}">${t('Create birthday card')}</button></div><strong class="agenda-countdown ${e.inDays===0?'is-today':''}">${e.inDays===0?t('Today!'):t('{days} away',{days:quantity(e.inDays,'day')})}</strong></article>`}).join(''):`<div class="empty search-empty"><h3>${t('No birthdays in this view')}</h3><p>${t('Try a longer range, both calendars, or another name.')}</p></div>`;
 $$('[data-agenda-card]').forEach(b=>b.onclick=()=>workbench.showCard(state.agendaEvents[+b.dataset.agendaCard]));
}
function setView(next){state.view=next;render()}
$$('[data-view]').forEach(b=>{b.onclick=()=>setView(b.dataset.view);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=$$('[data-view]'),index=tabs.indexOf(b),i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;setView(tabs[i].dataset.view);tabs[i].focus()}}});
$('#birthday-range').onchange=e=>{state.birthdayRange=Number(e.target.value);workbench.persist();renderAgenda()};$('#birthday-calendar').onchange=e=>{state.birthdayCalendar=e.target.value;workbench.persist();renderAgenda()};
function openCalendarExport(){
 if(state.demo||!state.agendaEvents.length)return;
 const events=[...state.agendaEvents];
 modal('Export calendar',`<p class="form-preview">${esc($('#agenda-summary').textContent)}</p><p class="hint">${t('Only the birthdays in your current view will be exported. The file contains these names and birthday dates:')}</p><div class="check-list">${[...new Set(events.map(e=>e.person.name))].map(name=>`<p class="check-row" dir="auto">${esc(name)}</p>`).join('')}</div>${events.some(e=>e.calendar==='g')?`<label class="check-row"><input id="repeat-gregorian" type="checkbox" checked>${t('Repeat Gregorian birthdays every year')}</label><p class="hint">${t('Yearly repeats continue beyond this date range. February 29 birthdays use the last day of February.')}</p>`:''}<p class="hint">${t('Hijri birthdays are dated events for the selected range. Future edits in Kin do not sync. Re-importing may create duplicates; remove older imports when replacing them.')}</p><div class="dialog-actions">${button('cancel-export','Cancel')}${button('download-calendar','Download calendar','primary')}</div>`);
 $('#cancel-export').onclick=close;
 $('#download-calendar').onclick=()=>{
 const content=createCalendar(events,{recurringGregorian:$('#repeat-gregorian')?.checked??false,summary:e=>t('{name} — {calendar} birthday',{name:e.person.name,calendar:calendarName(e.calendar)}),description:(e,{recurring})=>recurring?t('Yearly Gregorian birthday. Exported from Kin; changes to your family link do not sync.'):t('Turning {age}. {date}. Exported from Kin. One-time event; calendar imports do not sync with your family link.',{age:quantity(e.turns,'year'),date:date(e.day,e.calendar)})});
 const url=URL.createObjectURL(new Blob([content],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='kin-birthdays.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Calendar download started. Import the file into your calendar app.');close();
 };
};

function card(p){return personCard(p,state)}
function showDemo(){state.demo=true;state.people=[{id:'ZGVtbzAx',name:language()==='ar'?'آمنة':'Amina',day:inputDay('g',1991,4,18),calendar:'g'},{id:'ZGVtbzAy',name:language()==='ar'?'يوسف':'Yusuf',day:inputDay('g',2018,9,22),calendar:'g'},{id:'ZGVtbzAz',name:language()==='ar'?'ليلى':'Layla',day:inputDay('g',2022,2,14),calendar:'g'}];render();notice('You’re exploring an example family. These people are not saved.',()=>{state.people=[];state.demo=false;clearNotice();render();editPerson()},'Start my family')}
function editPerson(person){if(state.demo)return toast('Start your own family to add or edit people.');if(state.viewOnly)return toast('Merge this family before editing.');let calendar=person?.calendar||'g';const parts=person?calendars[calendar].parts(person.day):['','',''];
modal(person?'A little update':'Add someone you love',`<form id="person-form" novalidate><label class="form-field"><span>${t('Name')}</span><input name="name" id="person-name" required maxlength="80" autocomplete="off" dir="auto" placeholder="${t('e.g. Amina')}" value="${esc(person?.name||'')}"></label><div class="field-label">${t('Birth date')}</div><div class="segmented" role="group" aria-label="${t('Birth date calendar')}"><button type="button" class="has-icon" data-calendar="g">${icon('sun')}<span>${calendarName('g')}</span></button><button type="button" class="has-icon" data-calendar="h">${icon('moon')}<span>${calendarName('h')}</span></button></div><p class="hint" id="calendar-hint"></p><div class="date-fields"><label>${t('Day')}<input id="birth-day" type="text" inputmode="numeric" maxlength="2" required placeholder="${t('DD')}" value="${parts[2]}"></label><label>${t('Month')}<select id="birth-month" required></select></label><label>${t('Year')}<input id="birth-year" type="text" inputmode="numeric" maxlength="4" required placeholder="${t('YYYY')}" value="${parts[0]}"></label></div><p class="hint">${t('Arabic and Western digits are both accepted.')}</p><div id="date-preview" class="form-preview" hidden></div><div id="form-error" class="form-error" role="alert"></div><div class="dialog-actions">${person?button('remove-person','Remove','danger'):''}${button('cancel-person','Cancel')}${button('save-person',person?'Save changes':'Add to my circle','primary','submit')}</div></form>`);
const fields=['#person-name','#birth-day','#birth-month','#birth-year'];fields.forEach(s=>$(s).setAttribute('aria-describedby','form-error'));
const clearErrors=()=>{fields.forEach(s=>$(s).removeAttribute('aria-invalid'));$('#form-error').textContent=''};fields.forEach(s=>$(s).addEventListener('input',clearErrors));
const getDay=()=>inputDay(calendar,parseDigits($('#birth-year').value),parseDigits($('#birth-month').value),parseDigits($('#birth-day').value));
const preview=()=>{try{const d=getDay();$('#date-preview').hidden=false;$('#date-preview').textContent=`${date(d,calendar==='g'?'h':'g')} · ${t('Born on a {day}',{day:weekday(d)})}`;$('#form-error').textContent=''}catch{$('#date-preview').hidden=true}};
function calendarUI(month){$$('[data-calendar]').forEach(b=>{b.classList.toggle('active',b.dataset.calendar===calendar);b.setAttribute('aria-pressed',b.dataset.calendar===calendar)});$('#birth-month').innerHTML=`<option value="">${t('Month')}</option>`+months(calendar).map((m,i)=>`<option value="${i+1}" ${i+1===+month?'selected':''}>${m}</option>`).join('');$('#calendar-hint').textContent=t(calendar==='h'?'Umm al-Qura calendar · local moon sightings may differ.':'Enter the date as it appears on their birth record.');preview()}
calendarUI(parts[1]);$$('[data-calendar]').forEach(b=>b.onclick=()=>{if(b.dataset.calendar===calendar)return;let d;try{d=getDay()}catch{if(['#birth-year','#birth-month','#birth-day'].some(s=>$(s).value.trim())){$('#form-error').textContent=t('Complete a valid birth date before switching calendars. Your entries have been kept.');$('#birth-day').focus();return}}calendar=b.dataset.calendar;if(d!==undefined){const [y,m,day]=calendars[calendar].parts(d);$('#birth-year').value=y;$('#birth-day').value=day;calendarUI(m)}else{$('#birth-year').value='';$('#birth-day').value='';calendarUI('')}});
['#birth-day','#birth-month','#birth-year'].forEach(s=>$(s).addEventListener('input',preview));$('#cancel-person').onclick=close;
$('#person-form').onsubmit=async e=>{e.preventDefault();clearErrors();let invalid='#person-name';try{const name=$('#person-name').value.trim().normalize('NFC');if(!name)throw Error('Please enter a name.');if(new TextEncoder().encode(name).length>120)throw Error('Please use a shorter name (up to 120 UTF-8 bytes).');invalid=['#birth-day','#birth-month','#birth-year'].find(s=>!$(s).value.trim()||!Number.isSafeInteger(parseDigits($(s).value)))||'#birth-day';const year=parseDigits($('#birth-year').value);if(Number.isSafeInteger(year)&&(calendar==='g'?year<1900||year>new Date().getFullYear():year<1300||year>1600))invalid='#birth-year';const day=getDay();invalid='#person-name';const p={id:person?.id||id(),name,day,calendar};if(state.people.some(x=>x.id!==p.id&&x.name.toLocaleLowerCase()===name.toLocaleLowerCase()&&x.day===day))throw Error('This person is already in your family.');const rows=person?state.people.map(x=>x.id===p.id?p:x):[...state.people,p];validate(rows);$('#save-person').disabled=true;if(await commit(rows)){state.pendingDraft=null;close()}}catch(e){$('#form-error').textContent=errorText(e);$(invalid).setAttribute('aria-invalid','true');$(invalid).focus()}finally{if($('#save-person'))$('#save-person').disabled=false}};
const draftSignature=()=>JSON.stringify([$('#person-name').value,calendar,$('#birth-year').value,$('#birth-month').value,$('#birth-day').value]);const initialDraft=draftSignature();state.pendingDraft=()=>draftSignature()!==initialDraft;
$('#remove-person')?.addEventListener('click',()=>{if(confirmLeave())removePerson(person)});
}
function removePerson(person){modal('Remove from your circle?',`<p class="prose">${t('Remove {name} from this family link? Previously saved links will still contain their details.',{name:`<bdi><strong>${esc(person.name)}</strong></bdi>`})}</p><div class="dialog-actions">${button('keep-person','Keep person')}${button('confirm-remove','Remove person','danger')}</div>`);$('#keep-person').onclick=()=>editPerson(person);$('#confirm-remove').onclick=async()=>{const before=[...state.people];if(await commit(state.people.filter(p=>p.id!==person.id),{message:''})){close();state.undoState=before;const saved=encode(state.people);toast('Person removed.',async()=>{if(state.undoState&&encode(state.people)===saved){try{const latest=localStorage.getItem(STORE);if(latest!==saved){toast('Your family changed in another tab. Review it before undoing.');return}}catch{}await commit(state.undoState,{message:'Removal undone. Save your updated link.'})}})}}}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Link copied. Keep it somewhere safe.');if(text===familyURL(state.people))workbench.markKept(state.people);return true}catch{modal('Copy your family link',`<p class="hint">${t('Copy this link, then bookmark it or send it to your family.')}</p><textarea id="manual-copy" readonly dir="ltr" aria-label="${t('Family link')}">${esc(text)}</textarea>`);$('#manual-copy').select();return false}}
function share(){if(state.demo)return toast('Example data is not saved. Start your own family first.');if(!state.people.length)return;
modal('Share & backup',`<p class="hint">${t('Choose who belongs in this link. The recipient can open it on its own, or merge it with their family.')}</p><div id="share-selection"></div><p id="link-size" class="hint" hidden></p><textarea class="link-input" id="share-url" rows="2" readonly dir="ltr" aria-label="${t('Selected family link')}"></textarea><details class="qr-options"><summary class="has-icon">${icon('qr')}<span>${t('QR code')}</span>${icon('chevron')}</summary><div class="qr-wrap"><canvas id="qr" aria-label="${t('QR code for the selected family link')}" role="img"></canvas><p id="qr-caption"></p>${button('download-qr','Save QR')}</div></details><p class="share-warning" id="share-warning" hidden></p><p class="privacy-note">${t('Anyone with this link can read these names and birth dates. Encoding is not encryption. Share only with people you trust.')}</p><div class="dialog-actions share-controls">${button('copy-share','Copy link','primary')}${button('native-share','Share…')}${button('download-backup','Download backup')}</div>`);
mountSelection($('#share-selection'),state.people,{selected:workbench.visible().map(p=>p.id)});$('#share-selection .selection-count').id='share-count';
 $('#share-selection .selection-all').id='select-all';$$('#share-selection .selection-person').forEach(i=>i.classList.add('share-person'));
 function update(){const ids=$$('.share-person:checked').map(x=>x.value),selected=state.people.filter(p=>ids.includes(p.id));$('#select-all').checked=ids.length===state.people.length;$('#select-all').indeterminate=ids.length>0&&ids.length<state.people.length;$('#share-count').textContent=t('{selected} of {total} people',{selected:number(ids.length),total:number(state.people.length)});const url=selected.length?familyURL(selected):'';$('#share-url').value=url;$('#link-size').textContent=t('{count} characters',{count:number(url.length)});$('#link-size').hidden=url.length<2000;$('#download-backup').disabled=$('#copy-share').disabled=$('#native-share').disabled=!selected.length;$('#qr').hidden=true;$('#download-qr').disabled=true;$('#share-warning').hidden=url.length<2000;$('#share-warning').textContent=t('This is a long link. Some messaging apps may truncate it. Share fewer people and check that the full link arrived.');if(!selected.length){$('#qr-caption').textContent=t('Select at least one person.');return}try{if(url.length>2000)throw Error('long');const qr=new QRCode(-1,1);qr.addData(url);qr.make();const n=qr.getModuleCount(),scale=Math.max(3,Math.floor(320/(n+8))),canvas=$('#qr');canvas.width=canvas.height=(n+8)*scale;const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#24213d';for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(qr.isDark(r,c))ctx.fillRect((c+4)*scale,(r+4)*scale,scale,scale);canvas.hidden=false;$('#download-qr').disabled=false;$('#qr-caption').textContent=t('Scan to open this family circle')}catch{$('#qr-caption').textContent=t('Too much data for a comfortably scannable QR. Choose fewer people or copy the link.')}}
$('#download-backup').onclick=()=>{const ids=$$('.share-person:checked').map(x=>x.value);const records=state.people.filter(p=>ids.includes(p.id));if(!records.length)return;const url=URL.createObjectURL(new Blob([createBackup(records)],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='kin-family-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup download started. Keep the file somewhere safe.');workbench.markKept(records);};
$('#select-all').addEventListener('change',update);$$('.share-person').forEach(b=>b.addEventListener('change',update));$('#copy-share').onclick=()=>copy($('#share-url').value);$('#native-share').hidden=!navigator.share;$('#native-share').onclick=async()=>{try{await navigator.share({title:t('Our family on Kin'),url:$('#share-url').value})}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable here. Use Copy link.')}};$('#download-qr').onclick=()=>{const a=document.createElement('a');a.download='kin-family-qr.png';a.href=$('#qr').toDataURL('image/png');a.click()};update();
}
function importDialog(){if(state.demo)return toast('Example data is not saved. Start your own family first.');modal('Bring your circles together',`<p class="hint">${t('Paste a Kin link shared with you. You’ll review new people and any conflicting edits before anything is saved.')}</p><form id="import-form" novalidate><label class="form-field"><span>${t('Family link')}</span><textarea id="import-url" dir="ltr" required placeholder="${t('Paste a family link here…')}" spellcheck="false"></textarea></label><p id="import-error" class="form-error" role="alert"></p><div class="dialog-actions">${button('review-import','Review people','primary','submit')}</div></form><div class="backup-import"><label class="form-field"><span>${t('Or restore a backup file')}</span><input type="file" id="backup-file" accept=".json,application/json"></label><p class="hint">${t('Choose a Kin backup from this device. You will review the people before merging.')}</p><p id="backup-error" class="form-error" role="alert"></p></div>`);$('#import-form').onsubmit=e=>{e.preventDefault();try{const raw=$('#import-url').value.trim();let hash;if(raw.startsWith('#'))hash=raw;else{let u;try{u=new URL(raw)}catch{throw Error('Paste a valid web link.')}if(!['https:','http:'].includes(u.protocol))throw Error('Paste a valid web link.');hash=u.hash}review(decode(hash),false)}catch(e){$('#import-error').textContent=errorText(e)}};const fileInput=$('#backup-file'),fileError=$('#backup-error');fileInput.onchange=async()=>{const file=fileInput.files?.[0];if(!file)return;fileError.textContent='';fileInput.disabled=true;try{if(file.size>MAX_BACKUP_BYTES)throw Error('This backup is too large. Choose a Kin backup smaller than 64 KB.');const records=readBackup(await file.text().catch(()=>{throw Error('This backup could not be read. Choose another file.')}));if(!$('#modal').open||!fileInput.isConnected)return;review(records,false)}catch(e){if(fileError.isConnected)fileError.textContent=errorText(e)}finally{if(fileInput.isConnected){fileInput.disabled=false;fileInput.value=''}}}}
function review(incoming,fromURL){const existing=state.viewOnly?localFamily():state.people;if(state.viewOnly){state.people=existing;state.viewOnly=false;render()}const plan=mergePlan(existing,incoming);
modal('A family link, received',`<p class="hint">${t('{incoming} people in this link. Your current circle has {existing}.',{incoming:number(incoming.length),existing:number(existing.length)})}</p><div class="form-preview">${t('{added} new · {duplicates} already here · {conflicts} to review',{added:number(plan.added.length),duplicates:number(plan.duplicates.length),conflicts:number(plan.conflicts.length)})}</div>${plan.added.length?`<h3 class="field-label">${t('New people')}</h3><p class="hint">${t('Choose the new people you want to add. Unchecked people will not be imported.')}</p><div class="check-list">${plan.added.map(p=>`<label class="check-row"><input type="checkbox" class="merge-person" value="${p.id}" checked><span><bdi>${esc(p.name)}</bdi><span class="meta">${date(p.day)}</span></span></label>`).join('')}</div>`:''}${plan.conflicts.map(c=>`<div class="conflict"><strong dir="auto">${esc(c.local.name)}</strong><p>${t('Yours:')} <bdi>${esc(c.local.name)}</bdi> · ${date(c.local.day)} · ${t('Entered in {calendar}',{calendar:calendarName(c.local.calendar)})}</p><p>${t('Shared:')} <bdi>${esc(c.incoming.name)}</bdi> · ${date(c.incoming.day)} · ${t('Entered in {calendar}',{calendar:calendarName(c.incoming.calendar)})}</p><label><input type="checkbox" class="resolve-conflict" value="${c.local.id}">${t('Use the shared version instead')}</label></div>`).join('')}<p class="hint">${t('Unchecked conflicts keep your version. Merging adds people; it never imports deletions.')}</p><p class="form-error" id="merge-error" role="alert"></p><div class="dialog-actions">${button('cancel-merge','Cancel')}${fromURL?button('view-link','View only'):''}${button('confirm-merge',existing.length?'Merge with my family':'Keep this family','primary')}</div>`);
$('#confirm-merge').onclick=async()=>{try{const rows=merge(existing,plan,$$('.resolve-conflict:checked').map(x=>x.value),$$('.merge-person:checked').map(x=>x.value));if(await commit(rows,{message:'Family saved. Copy the updated link to keep it.'}))close()}catch(e){$('#merge-error').textContent=errorText(e)}};$('#cancel-merge').onclick=close;
$('#view-link')?.addEventListener('click',()=>{state.people=incoming;state.viewOnly=true;close();render();notice('Viewing a shared snapshot. Your saved circle has not changed.',()=>{state.people=existing;state.viewOnly=false;review(incoming,true);render()},'Merge with my family')});if(fromURL)$('#modal').onclose=()=>{if(!state.viewOnly)history.replaceState(null,'',location.pathname+(state.people.length?encode(state.people):''));$('#modal').onclose=null}
}
function help(){modal('A little guide to Kin',`<div class="prose">${helpSections.map(([tag,key])=>`<${tag}>${t(key)}</${tag}>`).join('')}<p><a href="https://developer.mozilla.org/en-US/docs/Web/URI/Reference/Fragment" target="_blank" rel="noreferrer">${t('How URL fragments work')}${icon('export')}</a></p></div>`)}
$('#skip-content').onclick=()=>$('#main-content').focus();
$('#add-button').onclick=()=>editPerson();$('#import-button').onclick=importDialog;$('#share-button').onclick=share;$('#sort').onchange=e=>{state.sort=e.target.value;render()};$('#family-search').oninput=e=>{state.search=e.target.value;render()};$('#about-button').onclick=help;
$('#language-button').onclick=()=>{setLanguage(language()==='ar'?'en':'ar');$('#toast').hidden=true;localizedShell();if(state.demo)showDemo();else render();drawUpdate()};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});$('#install-button').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('Keep Kin at your fingertips',`<div class="prose">${[['iPhone or iPad:','open Kin in Safari, tap Share, then Add to Home Screen.'],['Android:','open your browser menu and choose Install app or Add to Home Screen.'],['Desktop:','use the install icon in the address bar when your browser offers one.']].map(([a,b])=>`<p><strong>${t(a)}</strong> ${t(b)}</p>`).join('')}<p>${t('Bookmark your family link separately. The installed app uses this device’s latest local copy; your bookmark is the portable backup.')}</p></div>`)};
let updateReady=false,waitingWorker=null,reloadForUpdate=false;
function drawUpdate(){const el=$('#update-notice');el.hidden=!updateReady;if(updateReady){el.textContent=t('A new version is ready. Reload when you’ve finished editing.');const b=document.createElement('button');b.textContent=t('Reload');b.onclick=()=>{if(!confirmLeave())return;reloadForUpdate=true;if(waitingWorker)waitingWorker.postMessage({type:'SKIP_WAITING'});else location.reload()};el.append(b)}}
async function start(){localizedShell();state.people=localFamily();render();window.kinStartupReady?.();if(location.hash){try{const incoming=decode(location.hash);if(encode(incoming)===encode(state.people))render();else if(state.people.length)review(incoming,true);else await commit(incoming,{message:''})}catch(e){damagedLink(e)}}else if(state.people.length)history.replaceState(null,'',location.pathname+encode(state.people));
if(import.meta.env?.DEV){offlineState='unsupported';offlineUI();return}
if('serviceWorker'in navigator){try{const controlled=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{offlineState='ready';offlineUI();if(reloadForUpdate){location.reload();return}if(controlled){updateReady=true;drawUpdate()}});const registration=await navigator.serviceWorker.register('./sw.js');const readyUpdate=()=>{if(registration.waiting&&registration.active){waitingWorker=registration.waiting;updateReady=true;drawUpdate()}};readyUpdate();registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')readyUpdate()})});let readyTimer;try{await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>{readyTimer=setTimeout(()=>reject(new Error('Offline installation timed out')),25000)})])}finally{clearTimeout(readyTimer)}offlineState='ready';offlineUI();navigator.storage?.persist?.().catch(()=>{})}catch{offlineState='failed';offlineUI()}}else{offlineState='unsupported';offlineUI()}}
window.addEventListener('hashchange',()=>{try{if(location.hash){const incoming=decode(location.hash);if(!confirmLeave()){history.replaceState(null,'',location.pathname+(state.people.length?encode(state.people):''));return}review(incoming,true)}}catch(e){damagedLink(e)}});
window.addEventListener('storage',e=>{if(e.key===STORE||e.key===null)notice('Your family changed in another tab. Review it before continuing.',reviewLatest,'Review changes')});
window.addEventListener('online',offlineUI);window.addEventListener('offline',offlineUI);setInterval(()=>{if(state.reference===null&&today()!==state.now)render()},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.reference===null&&today()!==state.now)render()});start();
